gboolean handle_new_file_transfer(gpointer data, gint fd, b_input_condition cond) {
    TransferData *transfer_data = (TransferData *)data;
    if (!transfer_data) {
        return FALSE;
    }

    Connection *connection = transfer_data->connection;
    if (!connection) {
        return FALSE;
    }

    Buddy *buddy = find_buddy(connection, transfer_data->buddy_id);
    if (!buddy) {
        return FALSE;
    }

    FileTransfer *file_transfer = start_file_transfer(buddy, transfer_data->file_path);
    if (!file_transfer) {
        return FALSE;
    }

    setup_transfer_callbacks(file_transfer);
    associate_data_with_transfer(file_transfer, transfer_data);

    return FALSE;
}
